{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE MapleMonk.Founders_Dashboard_Target_vs_Achievement AS WITH Metric_Level_Target AS ( SELECT metric_map.Dashboard_Metric AS Metric, DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) AS Target_Date, CAST(t.Target AS FLOAT64) / (DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY) + 1) AS Target, CASE WHEN CURRENT_DATE() > DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY) THEN 0 ELSE DATE_DIFF(LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY)), CURRENT_DATE(), DAY) + 1 END AS days_Remaining, EXTRACT(DAY FROM LAST_DAY(DATE_ADD(DATE(t.Start_Date), INTERVAL n DAY))) AS no_of_days FROM `MapleMonk.Zouk_Targets` t JOIN ( SELECT \'Net Revenue\' AS Target_Metric, \'NET_REVENUE\' AS Dashboard_Metric UNION ALL SELECT \'COGS\', \'COGS\' UNION ALL SELECT \'Performance Marketing Spends\', \'PERFORMANCE_MARKETING_SPENDS\' UNION ALL SELECT \'CM2\', \'CM2\' UNION ALL SELECT \'Net Revenue ECOMMERCE\', \'NET_REVENUE_ECOMMERCE\' UNION ALL SELECT \'Net_Revenue_QCOMMERCE\', \'NET_REVENUE_QCOMMERCE\' UNION ALL SELECT \'Net Revenue DTC\', \'NET_REVENUE_D2C\' UNION ALL SELECT \'Net Revenue Offline\', \'NET_REVENUE_OFFLINE\' UNION ALL SELECT \'Net Revenue Bags\', \'NET_REVENUE_BAGS\' UNION ALL SELECT \'Net Revenue Backpacks\', \'NET_REVENUE_BACKPACKS\' UNION ALL SELECT \'Net Revenue Trolley and Duffel\', \'NET_REVENUE_TROLLEY_DUFFEL\' UNION ALL SELECT \'Net Revenue Others\', \'NET_REVENUE_OTHERS\' UNION ALL SELECT \'Full Kits Dispatched\', \'FULL_KITS_DISPATCHED\' UNION ALL SELECT \'Inward Quantity\', \'INWARD_QUANTITY\' UNION ALL SELECT \"Net Revenue Men\'s Collection\", \'NET_REVENUE_MENS_COLLECTION\' UNION ALL SELECT \'Net Revenue Rhea Kapoor Collection\', \'NET_REVENUE_RHEA_COLLECTION\' UNION ALL SELECT \'Net Revenue Low DRR\', \'NET_REVENUE_LOW_DRR\' ) AS metric_map ON TRIM(t.Metrics) = metric_map.Target_Metric CROSS JOIN UNNEST(GENERATE_ARRAY(0, DATE_DIFF(DATE(t.End_Date), DATE(t.Start_Date), DAY))) AS n ), Metric_Level_Achievement AS ( SELECT Date,\'NET_REVENUE\' AS Metric, SUM(Net_Revenue) AS Achievement FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'COGS\', SUM(COGS) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'PERFORMANCE_MARKETING_SPENDS\', SUM(Performance_Marketing_Spends) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'CM2\', SUM(CM2) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'MRP_SALES\', SUM(MRP_Sales) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'NET_REVENUE_BAGS\', SUM(Net_Revenue_Bags) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'NET_REVENUE_BACKPACKS\', SUM(Net_Revenue_Backpacks) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'NET_REVENUE_TROLLEY_DUFFEL\', SUM(Net_Revenue_Trolley_Duffel) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'NET_REVENUE_OTHERS\', SUM(Net_Revenue_Others) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'NET_REVENUE_ECOMMERCE\', SUM(Net_Revenue_ECOMMERCE) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'NET_REVENUE_QCOMMERCE\', SUM(Net_Revenue_QCOMMERCE) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'NET_REVENUE_D2C\', SUM(Net_Revenue_D2C) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'NET_REVENUE_OFFLINE\', SUM(Net_Revenue_Offline) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'INWARD_QUANTITY\', SUM(Inward_Quantity) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'FULL_KITS_DISPATCHED\', SUM(Full_Kits_Dispatched) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'NET_REVENUE_MENS_COLLECTION\', SUM(Net_Revenue_Mens_Collection) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'NET_REVENUE_RHEA_COLLECTION\', SUM(Net_Revenue_Rhea_Collection) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date UNION ALL SELECT Date, \'NET_REVENUE_LOW_DRR\', SUM(Net_Revenue_Low_DRR) FROM MapleMonk.Zouk_Founders_Dashboard WHERE Date < CURRENT_DATE() GROUP BY Date ), Combined_Data AS ( SELECT COALESCE(t.Target_Date, a.Date) AS Date, COALESCE(t.Metric, a.Metric) AS Metric, t.Target, t.Days_Remaining, t.No_of_Days, IFNULL(a.Achievement, 0) AS Achievement FROM Metric_Level_Target t FULL OUTER JOIN Metric_Level_Achievement a ON t.Target_Date = a.Date AND TRIM(UPPER(t.Metric)) = TRIM(UPPER(a.Metric)) ) SELECT Date, LOWER(Metric) as Metrics, Target, Achievement, Days_Remaining, No_of_Days FROM Combined_Data ORDER BY Date, Metric;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            